<?php declare(strict_types=1);namespace App\Core;use PDO;final class Database{private PDO $pdo;public function __construct(Config $c){$d=$c->get('db');$dsn="mysql:host={$d['host']};port={$d['port']};dbname={$d['database']};charset={$d['charset']}";$this->pdo=new PDO($dsn,$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC,PDO::ATTR_EMULATE_PREPARES=>false]);}public function pdo():PDO{return $this->pdo;}public function fetch(string $sql,array $params=[]):?array{$s=$this->pdo->prepare($sql);$s->execute($params);$r=$s->fetch();return $r?:null;}public function all(string $sql,array $params=[]):array{$s=$this->pdo->prepare($sql);$s->execute($params);return $s->fetchAll();}public function execute(string $sql,array $params=[]):bool{$s=$this->pdo->prepare($sql);return $s->execute($params);}public function id():string{return $this->pdo->lastInsertId();}}
